import sys, math, random, heapq
from collections import deque
from math import gcd

def bs(arr, le, ri):
	l = 0
	arr.sort()
	r = len(arr) - 1
	ans = 10000000
	while l <= r:
		m = (l + r) // 2
		if arr[m] >= le and arr[m] <= ri:
			ans = arr[m]
			r = m - 1
		elif arr[m] < le:
			l = m + 1
		else:
			r = m - 1
	return ans
for __ in range(int(input())):
	(n, m, k) = map(int, input().split())
	l = [[-1 for j in range(m)] for i in range(n)]
	ans = [[0 for j in range(m)] for i in range(n)]
	largest = [[0 for i in range(m)] for j in range(n)]
	for i in range(n * m):
		(x, y) = map(int, input().split())
		l[x - 1][y - 1] = (i % 2, i)
	for i in range(n):
		ans[i][0] = l[i][0][0]
		for j in range(1, m):
			ans[i][j] = l[i][j][0] + ans[i][j - 1]
	for j in range(m):
		for i in range(1, n):
			ans[i][j] += ans[i - 1][j]
	for i in range(n):
		st = deque()
		for j in range(k):
			while len(st) > 0 and st[-1][0] < l[i][j][1]:
				st.pop()
			st.append((l[i][j][1], j))
		largest[i][k - 1] = st[0][0]
		for j in range(k, m):
			if st[0][1] == j - k:
				st.popleft()
			while len(st) > 0 and st[-1][0] < l[i][j][1]:
				st.pop()
			st.append((l[i][j][1], j))
			largest[i][j] = st[0][0]
	for i in range(k - 1, m):
		st = deque()
		for j in range(k):
			while len(st) > 0 and st[-1][0] < largest[j][i]:
				st.pop()
			st.append((largest[j][i], j))
		largest[k - 1][i] = st[0][0]
		for j in range(k, n):
			if st[0][1] == j - k:
				st.popleft()
			while len(st) > 0 and st[-1][0] < largest[j][i]:
				st.pop()
			st.append((largest[j][i], j))
			largest[j][i] = st[0][0]
	alice = []
	bob = []
	for i in range(k - 1, n):
		for j in range(k - 1, m):
			x = ans[i][j]
			if i - k >= 0:
				x -= ans[i - k][j]
			if j - k >= 0:
				x -= ans[i][j - k]
			if i - k >= 0 and j - k >= 0:
				x += ans[i - k][j - k]
			if x == 0:
				alice.append(largest[i][j])
			if x == k * k:
				bob.append(largest[i][j])
	if len(bob) == 0 and len(alice) == 0:
		print('Draw')
	elif len(bob) == 0:
		print('Alice')
	elif len(alice) == 0:
		print('Bob')
	else:
		print('Bob') if min(alice) > min(bob) else print('Alice')
